// 佛腳筆記：文法 A 組（時間、條件、原因理由、目的、逆接讓步、對比）
Bank.addNotes('g-a', 'grammar', [
  // [句型, 接續, 中文意思, 例句, 例句中譯, 易錯提醒]

  // ── 時間 ──
  ['〜うちに', '動詞辞書形／ている形／ない形・い形・な形＋な・名詞＋の', '趁著…的時候（在狀態改變前把握時機）；在…期間不知不覺起了變化', '若いうちに、いろいろな国へ行ってみたい。', '我想趁年輕時去各個國家看看。', '「うちに」強調「狀態改變前趕快做」，「間に」只單純指某段期間內；「若い間に旅行したい」不自然。'],
  ['〜間', '動詞辞書形／ている形・い形・な形＋な・名詞＋の', '在…的整段期間，一直…', '夏休みの間、毎日図書館で勉強した。', '暑假期間，我每天都在圖書館讀書。', '「間」後面接整段期間持續的動作或狀態（ずっと〜ていた）；「間に」後面接期間內某一時點發生的一次性動作。'],
  ['〜間に', '動詞辞書形／ている形・い形・な形＋な・名詞＋の', '在…期間內（的某個時點）做了某事', '母が買い物に行っている間に、部屋を片付けた。', '媽媽出去買東西的期間，我把房間整理好了。', '「間に」只表示期間內的某一時點，沒有「趁機、錯過就來不及」的語感；有這種緊迫感時用「うちに」。'],
  ['〜ないうちに', '動詞ない形', '在還沒…之前（趁還沒發生）', '暗くならないうちに、家へ帰ろう。', '趁天還沒黑，回家吧。', '意思接近「〜前に」，但帶有「不快點就會發生不好的事」的緊迫感；也可表示不知不覺（知らないうちに眠っていた）。'],
  ['〜たびに', '動詞辞書形・名詞＋の', '每次…就…（每逢都會發生同樣的事）', 'この歌を聞くたびに、高校時代を思い出す。', '每次聽到這首歌，我就會想起高中時代。', '動詞接辭書形，不能用た形（✕聞いたたびに）；後句是每次都會發生的事，不用於只發生一次的情況。'],
  ['〜たとたん（に）', '動詞た形', '剛一…就（意外地）…', '立ち上がったとたん、めまいがした。', '一站起來就感到頭暈。', '後句是說話者意料之外、已發生的事，不能接自己的意志動作、命令或請求（✕家に着いたとたん、電話してください）。'],
  ['〜最中に', '動詞ている形・名詞＋の', '正在…的時候（突然發生了別的事）', '会議の最中に、携帯電話が鳴ってしまった。', '開會開到一半時，手機響了。', '用於進行中的事被打斷的情境，後句多為突發事件；動詞必須用ている形（✕話す最中に）。'],
  ['〜るところだ', '動詞辞書形', '正要…（動作即將開始）', 'これから晩ご飯を作るところです。', '我現在正要做晚餐。', '辭書形＋ところ＝即將；ている形＋ところ＝正在；た形＋ところ＝剛完成。三者常一起考，看動詞形態判斷。'],
  ['〜ているところだ', '動詞ている形', '正在…（動作進行中）', '今、レポートを書いているところだから、少し待って。', '我現在正在寫報告，稍等一下。', '強調「正處於這個階段」，常用來回答現在在做什麼；與「〜最中」相比語氣較輕，不帶被打斷的含意。'],
  ['〜たところだ', '動詞た形', '剛…完（動作剛結束）', 'ちょうど今、駅に着いたところです。', '我現在剛到車站。', '只表示動作剛結束的時點，常與「今」「ちょうど」連用；不能和「先週」「去年」等較遠的時間一起用。'],
  ['〜たばかりだ', '動詞た形', '才剛…不久（說話者主觀覺得時間很短）', '先月買ったばかりのパソコンが、もう壊れた。', '上個月才剛買的電腦已經壞了。', '「たばかり」可用於較久以前（上個月、去年），「たところ」不行（✕先月買ったところだ）；別和「〜ばかりに（只因為）」混淆。'],
  ['〜てからでないと', '動詞て形', '不先…就不能…（必須先完成前項）', '手を洗ってからでないと、おやつを食べてはいけません。', '不先洗手就不可以吃點心。', '後句一定是否定或困難的表達（〜ない、〜できない、無理だ）；也可說「〜てからでなければ」。'],
  ['〜て以来', '動詞て形・名詞', '自從…以來，一直…', '日本に来て以来、毎日日本語で日記を書いている。', '自從來日本之後，我每天都用日文寫日記。', '後句是從那時起持續至今的狀態，不能接一次性的事（✕来て以来、一度京都へ行った）。'],
  ['〜てはじめて', '動詞て形', '…之後才（第一次體會到）…', '病気になってはじめて、健康の大切さがわかった。', '生病之後才明白健康的重要。', '後句多是「わかる・気づく・知る」等領悟類動詞，不能接說話者的意志或請求。'],
  ['〜かと思ったら', '動詞た形', '才以為…，（沒想到）馬上就…', '晴れたかと思ったら、また雨が降り出した。', '才以為天放晴了，沒想到又下起雨來。', '用於描述眼前事物或他人的變化，不能用於自己的行為；也可說「〜かと思うと」。'],
  ['〜から〜にかけて', '名詞', '從…到…（期間或地區的大致範圍）', '今夜から明日の朝にかけて、強い雨が降るでしょう。', '從今晚到明天早上，將會下大雨。', '「から〜まで」起訖點明確；「にかけて」只表示大概範圍，常見於天氣預報。'],
  ['〜次第', '動詞ます形・名詞', '一…就馬上…', '資料が届き次第、すぐにお送りします。', '資料一送到，就立刻寄給您。', '後句是說話者的意志或請求，不能接已發生的事實（✕駅に着き次第、雨が降った）；這點和「たとたん」正好相反。'],
  ['〜際（に）', '動詞辞書形／た形・名詞＋の', '…的時候（正式、書面）', 'お降りの際は、お忘れ物のないようご注意ください。', '下車時請注意不要遺忘隨身物品。', '意思同「〜とき」，但用於廣播、公告、商務等正式場合，日常閒聊很少用。'],
  ['〜たところ', '動詞た形', '做了…之後，結果（得知）…', '店に問い合わせたところ、もう売り切れだと言われた。', '向店家詢問之後，被告知已經賣完了。', '後句是做了前項之後才知道的結果；與表「剛…完」的「〜たところだ」不同，這裡後面直接接下文。'],
  ['〜ついでに', '動詞辞書形／た形・名詞＋の', '順便…（做主要的事時，順帶做另一件事）', '郵便局へ行くついでに、この手紙も出してくれる？', '你去郵局時，可以順便幫我寄這封信嗎？', '前句是主要目的、後句是順帶的事；和「〜ながら」（兩個動作同時進行）不同。'],
  ['〜とおり（に）', '動詞辞書形／た形・名詞＋の（名詞直接接時為「どおり」）', '按照…；正如…', '先生に言われたとおりに、もう一度やってみた。', '照著老師說的再做了一次。', '名詞可直接接「どおり」，讀音會濁化（予定どおり、説明書どおり）；接「の」時則是「名詞＋のとおり」。'],
  ['〜まま', '動詞た形／ない形・い形・な形＋な・名詞＋の', '保持…的狀態（就那樣…）', '眼鏡をかけたまま、お風呂に入ってしまった。', '我戴著眼鏡就進去洗澡了。', '動詞要用た形（✕かけるまま）；表示本該改變的狀態沒變，常帶「不自然、不小心」的語感。'],

  // ── 條件・假設 ──
  ['〜たら', '動詞た形＋ら・い形かったら・な形／名詞だったら', '如果…的話；…之後（前項實現後）', '駅に着いたら、電話してください。', '到車站後請打電話給我。', '後句可接命令、請求、意志，用途最廣；「と」「ば」（前句為動作時）後句一般不能接意志表達（✕駅に着くと、電話してください）。'],
  ['〜ば', '動詞ば形・い形ければ・な形／名詞なら（であれば）', '如果…就…（一般條件，強調前項是成立條件）', 'この薬を飲めば、すぐ熱が下がりますよ。', '吃了這個藥，燒很快就會退喔。', '前句是動作動詞時，後句不宜接命令、請求（✕駅に着けば、電話してください→用「着いたら」）；前句是狀態（安ければ、時間があれば）時則可以。'],
  ['〜と', '動詞辞書形／ない形・い形・な形／名詞だ（現在普通形）', '一…就…（必然結果、自然現象、習慣、操作說明）', 'このボタンを押すと、お湯が出ます。', '按下這個按鈕，就會出熱水。', '後句是必然會發生的結果，不能接意志、命令、請求（✕春になると、旅行しましょう）；用於過去時表示「一…就發現」（窓を開けると、雪が降っていた）。'],
  ['〜なら', '動詞・い形普通形・な形語幹／名詞（直接接）', '如果是…的話（承接對方話題，提出建議或判斷）', '京都へ行くなら、紅葉の季節がいいですよ。', '如果要去京都的話，楓葉季節比較好喔。', '「なら」後句可以比前句先發生（行くなら、先に予約しておいて）；「たら」一定是前句先實現（✕行ったら、先に予約しておいて）。'],
  ['〜としたら／〜とすれば', '普通形', '假如…的話（假設前提，再做判斷）', 'もし宝くじが当たったとしたら、何に使いますか。', '假如中了彩券，你會拿來做什麼？', '用於不一定會實現的假設，後句多為說話者的推測、疑問或判斷；和「〜としても（即使）」只差一字，意思相反要看清楚。'],
  ['〜さえ〜ば', '名詞＋さえ＋動詞ば形・い形ければ・な形なら；動詞ます形＋さえすれば', '只要…就…（唯一的必要條件）', '住所さえわかれば、地図ですぐ調べられます。', '只要知道地址，就能用地圖馬上查到。', '「さえ」單獨用是「連…都」（水さえ飲めない），和「ば」搭配才是「只要」；動詞形式是「ます形＋さえすれば」（練習しさえすれば）。'],
  ['〜ば〜ほど', '動詞・い形的ば形＋同一詞辞書形；な形：〜なら〜なほど', '越…越…', 'この本は読めば読むほど面白くなる。', '這本書越讀越有趣。', '前後是同一個詞重複（高ければ高いほど）；也可省略前半只說「〜ほど」（練習するほど上手になる）。'],
  ['〜ばよかった', '動詞ば形（否定：〜なければ）', '要是…就好了（對過去的後悔、遺憾）', 'もっと早く家を出ればよかった。', '要是早點出門就好了。', '否定形是「〜なければよかった」（言わなければよかった）；「〜たらよかった」意思相同，較口語。用在別人身上帶輕微責備。'],
  ['〜からには', '普通形（な形・名詞＋である）', '既然…就（一定要、應該）…', '約束したからには、必ず守ります。', '既然約好了，就一定會遵守。', '後句多為決心、義務、勸告（〜つもりだ、〜べきだ、〜なければならない），不接單純的事實描述。'],
  ['〜以上（は）', '普通形（な形・名詞＋である）', '既然…就…（責任、決心，較書面）', 'チームに入った以上は、練習を休むわけにはいかない。', '既然加入了隊伍，就不能不去練習。', '和「からには」幾乎可互換；別和表數量的「〜以上」（三人以上）混淆。'],

  // ── 原因・理由 ──
  ['〜おかげで', '普通形（な形＋な・名詞＋の）', '多虧…（正面結果，含感謝）', '先輩が手伝ってくれたおかげで、仕事が早く終わった。', '多虧前輩幫忙，工作提早完成了。', '好結果用「おかげで」，壞結果用「せいで」；但反諷時也可用「おかげで」接壞結果（君のおかげで遅刻したよ）。'],
  ['〜せいで', '普通形（な形＋な・名詞＋の）', '都怪…；由於…（負面結果，帶責怪語氣）', '寝坊したせいで、電車に乗り遅れた。', '都怪睡過頭，沒趕上電車。', '只用於壞結果；「〜せいか」表示「也許是因為…」（年のせいか、疲れやすい），語氣較不確定。'],
  ['〜ために（原因）', '普通形（な形＋な・名詞＋の）', '因為…（較書面，客觀說明原因）', '大雪のために、電車が止まっています。', '因為大雪，電車停駛了。', '原因的「ために」前面可接過去式或狀態（事故があったために）；目的的「ために」只接意志動詞辭書形。後句不能接請求、命令。'],
  ['〜によって（原因）', '名詞', '因為…；由於…（書面語）', '台風によって、多くの家が被害を受けた。', '由於颱風，許多房屋受到損害。', '常見於新聞報導；修飾名詞時用「〜による＋名詞」（地震による被害）。另有被動句表動作者的用法（この寺は有名な僧によって建てられた）。'],
  ['〜によって（手段）', '名詞', '藉由…；透過…（方法、手段）', 'インターネットによって、世界中の情報が手に入るようになった。', '透過網路，可以取得全世界的資訊。', '比「で」更書面、正式；日常的交通工具等不會說「バスによって行く」，用「バスで行く」。'],
  ['〜によって（差異）', '名詞', '依…而不同（因人、因地而異）', '国によって、食事のマナーが違う。', '餐桌禮儀因國家而異。', '後句常接「違う」「異なる」「さまざまだ」；「〜によっては」表示「依情況，有的會…」（人によっては辛く感じる）。'],
  ['〜のだから', '普通形（な形・名詞＋な）', '既然…（當然…）；就是因為…（強調雙方都知道的理由）', 'せっかく来たんだから、ゆっくりしていってください。', '難得來了，就多待一會兒吧。', '前句是雙方都承認的事實，後句常接主張、建議或責備；語氣比單純的「から」更強。'],
  ['〜ばかりに', '普通形（な形＋な・名詞＋である）', '只因為…（才導致不好的結果，帶後悔）', '一言多く言ったばかりに、友達を怒らせてしまった。', '只因為多說了一句話，惹朋友生氣了。', '只用於負面結果；別和「〜たばかり（剛…）」混淆。'],
  ['〜ことから', '普通形（な形＋な／である・名詞＋である）', '由於…（作為判斷根據或名稱由來）', '道がぬれていることから、夜中に雨が降ったとわかった。', '從路面是濕的這點，知道半夜下過雨。', '多用於說明判斷依據或名稱由來，屬書面語；不用於日常個人行為的理由（✕お腹がすいたことから、ご飯を食べた）。'],

  // ── 目的 ──
  ['〜ために（目的）', '動詞辞書形・名詞＋の', '為了…（意志性的目的）', '留学するために、毎月お金をためています。', '為了留學，我每個月都在存錢。', '前後主語相同，且前句須是意志動詞；前句是非意志動詞（わかる、できる、なる）、可能形或主語不同時，要用「〜ように」。'],
  ['〜ように（目的）', '動詞辞書形／ない形・可能形', '為了能…；為了不要…（目標是狀態或能力）', '後ろの人にも聞こえるように、大きな声で話してください。', '為了讓後面的人也聽得到，請大聲說話。', '前面多接可能形、無意志動詞或ない形（✕聞こえるために）；前面是意志動詞且主語相同時則用「ために」。'],
  ['〜のに（用途）', '動詞辞書形＋のに・名詞＋に', '用於…；做…時（目的、用途）', 'このかばんは旅行に行くのに便利だ。', '這個包包去旅行時很方便。', '後句常接「便利だ・必要だ・使う・かかる」；和逆接的「のに（明明…）」形式相同，要看後句判斷。'],

  // ── 逆接・讓步 ──
  ['〜ても', '動詞て形・い形くても・な形／名詞でも', '即使…也…', '雨が降っても、試合は行われます。', '即使下雨，比賽也照常舉行。', '接名詞、な形用「でも」；疑問詞＋ても表示「不管…都」（何回聞いても、よくわからない）。'],
  ['たとえ〜ても', 'たとえ＋動詞て形・い形くても・な形／名詞でも', '就算（假設極端情況）…也…', 'たとえ親に反対されても、この仕事を続けたい。', '就算被父母反對，我也想繼續這份工作。', '「たとえ」必須與「ても／でも」呼應，不能接「たら」「ば」（✕たとえ反対されたら）。'],
  ['〜としても', '普通形', '即使…也…（明確假設的讓步）', '今から急いだとしても、もう間に合わないだろう。', '即使現在開始趕，大概也來不及了吧。', '比「ても」更強調前項是假設；別和「〜としたら（假如）」看錯。'],
  ['〜のに（逆接）', '普通形（な形・名詞＋な）', '明明…卻…（帶不滿、意外、遺憾）', '一生懸命勉強したのに、試験に落ちてしまった。', '明明拚命念書了，考試卻沒過。', '「のに」帶說話者的不滿或遺憾，「けど／が」只是單純逆接；後句不能接意志、命令、請求。'],
  ['〜くせに', '普通形（な形＋な・名詞＋の）', '明明…卻…（責備、輕視的語氣，口語）', '自分ではできないくせに、人にばかり文句を言う。', '自己明明做不到，卻只會抱怨別人。', '比「のに」更帶批評，多用於他人而非自己；前後主語必須相同。'],
  ['〜ながら（も）', '動詞ます形・い形・な形語幹・名詞', '雖然…但是…（逆接，較書面）', '狭いながらも、駅に近くて便利な部屋だ。', '雖然狹小，卻是靠近車站的方便房間。', '表逆接時多接狀態性詞語（知っていながら、残念ながら）；和「一邊…一邊」的「ながら」形式相同，要看前後語意判斷。'],
  ['〜といっても', '普通形', '雖說…，但其實（程度沒那麼高）', '料理ができるといっても、簡単なものしか作れません。', '雖說會做菜，但只會做簡單的東西。', '後句用來修正、降低聽者可能的期待，不是單純的「雖然」。'],
  ['〜からといって', '普通形', '雖說…但也不能就因此…', '日本人だからといって、敬語が上手だとはかぎらない。', '就算是日本人，也不一定擅長敬語。', '後句常接否定（〜わけではない、〜とはかぎらない、〜てはいけない），否定「單憑前項就下結論」。'],
  ['〜とはかぎらない', '普通形', '不一定…；未必…', '値段が高い物が、いつもいい物だとはかぎらない。', '價格高的東西未必總是好東西。', '常與「必ずしも」「いつも」「誰でも」搭配；是部分否定（不一定都…），不是「〜ない」的全面否定。'],
  ['〜ものの', '普通形（な形＋な／である・名詞＋である）', '雖然…但是…（事情沒有如預期進展，書面）', '免許は取ったものの、まだ一人で運転するのは怖い。', '雖然拿到駕照了，但還是不敢一個人開車。', '前句是已成立的事實，後句說明沒有順利進展；不能用於假設（✕もし雨が降るものの）。'],
  ['〜にもかかわらず', '普通形（な形・名詞直接接或＋である）', '儘管…還是…（書面語）', '雨にもかかわらず、たくさんの人が集まった。', '儘管下雨，還是聚集了很多人。', '書面版的「のに」，但不帶強烈的不滿；後句不能接意志、命令、請求。'],

  // ── 對比・比較 ──
  ['〜わりに（は）', '普通形（な形＋な・名詞＋の）', '與…相比，出乎意料地…（比預期好或差）', 'この店は値段のわりに、料理がおいしい。', '這家店以價格來說，料理很好吃。', '可接い形、な形（安いわりに、静かなわりに）；「にしては」不接形容詞（✕安いにしては），這是兩者的接續差異。'],
  ['〜にしては', '名詞・動詞普通形', '以…來說，算是…（與該身分、條件不相符）', '初めて作ったにしては、よくできていますね。', '以第一次做來說，做得很好呢。', '前面多為具體事實（初めて、子ども、プロ），不接い形、な形；「わりに」則可接形容詞。'],
  ['〜かわりに', '動詞普通形・い形・な形＋な・名詞＋の', '代替…；作為交換…；雖然…但另一方面…', '今日は母のかわりに、私が晩ご飯を作った。', '今天由我代替媽媽做了晚餐。', '「名詞＋のかわりに」多為「代替」；「動詞＋かわりに」常表示交換（英語を教えるかわりに、日本語を教えてもらう）。'],
  ['〜にかわって', '名詞', '代替…（由別人代做原本該由某人做的事；較正式）', '社長にかわって、私がご挨拶いたします。', '由我代替社長向各位致意。', '只接名詞，多用於正式場合；也表示「取代」（人間にかわって、ロボットが働く）。'],
  ['〜反面', '普通形（な形＋な／である・名詞＋である）', '另一方面…（同一事物的正反兩面）', 'スマホは便利な反面、使いすぎると目に悪い。', '智慧型手機雖然方便，但另一方面用太多對眼睛不好。', '描述「同一事物」的兩面性；比較「兩個不同的事物」時多用「一方（で）」。'],
  ['〜一方（で）', '普通形（な形＋な／である・名詞＋である）', '一方面…另一方面…；相對地…（對比兩件事）', '都会では人口が増えている一方で、田舎では減っている。', '都市人口在增加，另一方面鄉下人口在減少。', '可對比兩個不同主體；另有「動詞辭書形＋一方だ」表示「越來越…」（悪くなる一方だ），形式相近要分清楚。'],
  ['〜に反して', '名詞', '與…相反（預想、期待、意願）', '予想に反して、試験はとても簡単だった。', '與預想相反，考試非常簡單。', '多接「予想・期待・意志」等名詞；修飾名詞時用「〜に反する＋名詞」或「〜に反した＋名詞」。'],

  // ── 變化・同時 ──
  ['〜とともに', '動詞辞書形・名詞', '和…一起；與…同時；隨著…', '経済の発展とともに、人々の生活も変わってきた。', '隨著經濟發展，人們的生活也改變了。', '有「一起」「同時」「隨著變化」三種意思；表變化時與「につれて」相近，但更書面。'],
  ['〜につれて', '動詞辞書形・名詞', '隨著…（逐漸變化）', '日本語が上手になるにつれて、日本での生活が楽しくなった。', '隨著日文變好，在日本的生活也變得愉快了。', '前後都必須是逐漸變化的事，不能接一次性的動作（✕結婚するにつれて）；後句不接意志表達。'],
  ['〜にしたがって', '動詞辞書形・名詞', '隨著…；依照…（規則、指示）', '係員の指示にしたがって、落ち着いて避難してください。', '請依照工作人員的指示，冷靜地避難。', '表「隨著」時可與「につれて」互換；但表「依照規則、指示」只能用「にしたがって」，不能用「につれて」。'],
]);
